import math

def ppi(w, h, size):
    return round(math.sqrt(w**2 + h**2) / size, 2)

def scan(width_in, height_in, dpi, depth):
    w = round(width_in * dpi)
    h = round(height_in * dpi)
    mb = round(depth / 8 * w * h / 1024**2, 1)
    return (w, h, mb)

