def cycle_ns(rate, unit):
    mult = {'Hz': 1, 'kHz': 10**3, 'MHz': 10**6, 'GHz': 10**9}[unit]
    return round(10**9 / (rate * mult), 4)

def run(memory):
    pc, acc = 0, 0
    while pc in memory:
        mar = pc
        pc = pc + 1
        mdr = memory[mar]
        cir = mdr
        op, n = cir
        if op == 'LOAD':
            acc = n
        elif op == 'ADD':
            acc = acc + n
        elif op == 'SUB':
            acc = acc - n
        elif op == 'MUL':
            acc = acc * n
    return acc

