def fragments(blocks, f):
    count = 0
    prev = None
    for b in blocks:
        if b == f and prev != f:
            count += 1
        prev = b
    return count

def defrag(blocks):
    order = []
    count = {}
    for b in blocks:
        if b is None:
            continue
        if b not in count:
            order.append(b)
            count[b] = 0
        count[b] += 1
    out = []
    for f in order:
        out += [f] * count[f]
    return out + [None] * (len(blocks) - len(out))
